using System;using System.IO;using System.Net;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;
class ClientNewsSmoke {
static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS: "+label);}
static Task<Tuple<HttpStatusCode,string>> Result(string body){var t=new TaskCompletionSource<Tuple<HttpStatusCode,string>>();t.SetResult(Tuple.Create(HttpStatusCode.OK,body));return t.Task;}
public static void Run(){string dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"localserver");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"client-version.txt"),"1.2.3-4");File.WriteAllText(Path.Combine(dir,"install-state.json"),"{\"version\":\"1.2.3-4\"}");File.WriteAllText(Path.Combine(dir,"client-release-notes.md"),"# ReRiff 1.2.3-4 — notes\nChanges \\\" & Unicode ü");
var uri=new Uri("http://127.0.0.1/classes/News");var json=new JavaScriptSerializer();var source=Result("{\"results\":[{\"objectId\":\"custom\",\"en\":\"Server post\"},{\"objectId\":\"ReRiffServerStatus\"},{\"objectId\":\"SingleplayerNews\"}],\"count\":3}");
var result=ReRiff.NewsHeaders.WithClientNews(source,uri,"GET").Result;var document=json.DeserializeObject(result.Item2) as Dictionary<string,object>;var rows=(object[])document["results"];Check(rows.Length==2&&Convert.ToInt32(document["count"])==2,"client notes prepended and count updated");Check((string)((Dictionary<string,object>)rows[1])["en"]=="Server post","custom server post preserved");Check((string)((Dictionary<string,object>)rows[0])["enTitle"]=="ReRiff 1.2.3-4","full experimental revision retained");Check(Object.ReferenceEquals(source,ReRiff.NewsHeaders.WithClientNews(source,new Uri("http://127.0.0.1/classes/Score"),"GET")),"non-News task unchanged");Check(Object.ReferenceEquals(source,ReRiff.NewsHeaders.WithClientNews(source,uri,"POST")),"writes unchanged");var canceled=new TaskCompletionSource<Tuple<HttpStatusCode,string>>();canceled.SetCanceled();Check(ReRiff.NewsHeaders.WithClientNews(canceled.Task,uri,"GET").IsCanceled,"cancellation retained");var fault=new TaskCompletionSource<Tuple<HttpStatusCode,string>>();fault.SetException(new IOException("original"));Check(ReRiff.NewsHeaders.WithClientNews(fault.Task,uri,"GET").IsFaulted,"transport failure retained");var request=WebRequest.Create(uri);ReRiff.NewsHeaders.Add(request);Check(request.Headers["X-ReRiff-Client-Version"]=="1.2.3-4","version header preserves prerelease");File.WriteAllText(Path.Combine(dir,"client-release-notes.md"),"# ReRiff 1.2.3-3 — stale");Check(Object.ReferenceEquals(source,ReRiff.NewsHeaders.WithClientNews(source,uri,"GET")),"stale notes rejected");}
}
